#define PI  3.14159265359
#define TAU 6.28318530718

// ---- globals filled in main() ----------------------------------------------
vec3  gC0, gC1, gC2, gC3;   // active 4-color palette
int   gNCol;                // how many of those colors the engine uses (2/3/4)
